<template>
  <div class="recharge-record">
    <title-line :goHome="true" :title="title" />
    <!-- <div class="wallet-mons">
      <div class="mons">{{ mons }} </div>
      <div class="text">{{ $t('ctjl.ctjl02') }}</div>
    </div> -->
    <van-tabs v-model="currentIndex" :before-change="beforeChange" :ellipsis="false" title-inactive-color="rgba(242,239,255,0.75)" style="margin-top: 0;" @change="getSubClass">
      <van-tab v-for="item in typeList" :key="item.value" :title="item.label">
        <div class="content">
          <div class="recordList">
            <div class="listBox">
              <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" :offset="50" @refresh="onRefresh">
                <van-list
                  v-model="loading"
                  :finished="finished"
                  :loading-text="$t('tzjl.tzjl50')"
                  finished-text=""
                  @load="onLoad"
                >
                  <is-empty v-if="dataList.length===0" />
                  <div v-else class="data-table">
                    <div class="table-thead">
                      <div v-if="currentIndex===0">{{ $t('czym.czym46') }}</div>
                      <div v-if="currentIndex===1">{{ $t('czym.czym48') }}</div>
                      <div>{{ $t('czym.czym47') }}</div>
                    </div>
                    <div class="table-body">
                      <div v-for="(item,index) in dataList" :key="index" class="item" @click="toDetail(item,currentIndex)">
                        <div class="left-span">
                          <div class="line">
                            <div class="coin-type">{{ item.paytype }}</div>
                            <div class="coin-amount">+{{ item.pmons }}</div>
                          </div>
                          <div class="line">
                            <div class="recharge-date">{{ item.paytime }}</div>
                            <div class="recharge-status"><span style="color: rgba(36,238,137,1);">·</span>{{ item.tname }}</div>
                          </div>
                        </div>
                        <svg-icon icon-class="进入详情_箭头" :width="16" :height="16" />
                      </div>
                    </div>
                  </div>

                </van-list>
              </van-pull-refresh>
            </div>
          </div>
          <!-- <div v-if="currentIndex===1" />
          <div v-if="currentIndex===2" />
          <div v-if="currentIndex===3" /> -->
        </div>
      </van-tab>
    </van-tabs>
