</template>
<script>
import TitleLine from '../modules/TitleLine'
import { toprecord, drawrecord } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    // currentValue: {
    //   type: Number,
    //   default: 0
    // }
  },
  data() {
    return {
      title: this.$t('ctjl.ctjl01'), // '充提记录',
      showPop: false,
      currentValue: '1',
      typeList: [{ label: this.$t('home.sy03'), value: 0 }, { label: this.$t('home.sy04'), value: 1 }],
      currentIndex: 0,
      dataList: [
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      ],
      mons: '',
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
    this.$route.query.currentIndex && (this.currentIndex = Number(this.$route.query.currentIndex))
  },
  methods: {
    toDetail(item, currentIndex) {
      localStorage.setItem('rechargeDetail', JSON.stringify(item))
      // this.$bus.$emit('rechargeDetail', item)
      this.$router.push({
        path: '/rechargeDetail',
        query: {
          currentIndex: currentIndex
        }
      })
    },
    beforeChange(){
      if(this.loading){
        return false
      }else{
        return true
      }
    },
    getSubClass(value, label) {
      this.currentIndex = value
      this.onRefresh()
    },
    async onLoad() {
      let res
      if (this.currentIndex === 0) {
        res = await toprecord({ type: '30', pages: this.pageNum })
      } else {
        res = await drawrecord({ type: '30', pages: this.pageNum })
      }
      this.mons = res.mons
      if (this.refreshing) {
        this.dataList = []
        this.refreshing = false
      }
      this.dataList = this.dataList.concat(res.datalist)
      // this.dataList = [
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功',pdirect:'提现' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ]
      this.loading = false
      this.pageNum++
      if (this.dataList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
